package com.opensocket.aievent.core.runtime;
import java.util.Set;import org.springframework.stereotype.Component;import com.opensocket.aievent.core.configuration.runtime.RuntimeConfigurationEffectiveValueResolver;
@Component public final class RuntimeDisconnectRuntimeConfigurationEffectiveValueResolver implements RuntimeConfigurationEffectiveValueResolver{
 private final RuntimeDisconnectRuntimeConfigurationView view; public RuntimeDisconnectRuntimeConfigurationEffectiveValueResolver(RuntimeDisconnectRuntimeConfigurationView view){this.view=view;} @Override public String owner(){return "CORE_RUNTIME_DISCONNECT";} @Override public Set<String> supportedKeys(){return RuntimeDisconnectRuntimeConfigurationView.ALL;} @Override public Object resolve(String key){return switch(key){
 case RuntimeDisconnectRuntimeConfigurationView.ENABLED->view.enabled();case RuntimeDisconnectRuntimeConfigurationView.DEFAULT_GATEWAY_BASE_URL->view.defaultGatewayBaseUrl();case RuntimeDisconnectRuntimeConfigurationView.GATEWAY_NODE_001->view.gatewayBaseUrls().getOrDefault("gateway-node-001","");case RuntimeDisconnectRuntimeConfigurationView.GATEWAY_NODE_002->view.gatewayBaseUrls().getOrDefault("gateway-node-002","");case RuntimeDisconnectRuntimeConfigurationView.GATEWAY_NODE_003->view.gatewayBaseUrls().getOrDefault("gateway-node-003","");case RuntimeDisconnectRuntimeConfigurationView.GATEWAY_REGISTRY_ENABLED->view.gatewayRegistryEnabled();case RuntimeDisconnectRuntimeConfigurationView.GATEWAY_REGISTRY_URL->view.gatewayRegistryUrl();case RuntimeDisconnectRuntimeConfigurationView.AUTHORIZATION_SCHEME->view.authorizationScheme();case RuntimeDisconnectRuntimeConfigurationView.REQUEST_TIMEOUT->view.requestTimeout().toString();default->throw new IllegalArgumentException("CORE_RUNTIME_DISCONNECT_RUNTIME_CONFIG_KEY_NOT_OWNED key="+key);};}}
